  "type": "object",
  "required": ["meta", "businessModelCanvas", "leanCanvas", "swot"],
  "properties": {
    "meta": {
      "type": "object",
      "required": ["businessName", "country", "readyToGenerate"],
      "properties": {
        "businessName": { "type": "string" },
        "country": { "type": "string" },
        "readyToGenerate": {
          "type": "boolean",
          "description": "Must be true. Set true only when the conversation is fully finished and the user confirmed the output."
