    "businessModelCanvas": {
      "type": "object",
      "required": ["generated"],
      "properties": {
        "generated": { "type": "boolean", "description": "True only if the user selected BMC." },
        "keyPartners": { "type": "array", "items": { "type": "string" } },
        "keyActivities": { "type": "array", "items": { "type": "string" } },
        "keyResources": { "type": "array", "items": { "type": "string" } },
