// n8n Code node — "Run Once for All Items"
// ZERO external dependencies — uses only Node's built-in `zlib` module.
// Safe for marketplace publishing: no npm installs, no NODE_FUNCTION_ALLOW_EXTERNAL needed.
// Input:  item.json matching canvas-schema.json (output of Structured Output Parser)
// Output: item.binary.data — xlsx file buffer

// ============================================================================
// MINIMAL ZIP WRITER (store only — zero require() calls, zero dependencies,
// not even Node built-ins. Files are uncompressed, so the .xlsx is a bit
// larger than an exceljs/zlib version, but it opens in Excel/Sheets/LibreOffice
// exactly the same way.)
// ============================================================================

function crc32(buf) {
  let c;
  const table = crc32.table || (crc32.table = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      c = n;
      for (let k = 0; k < 8; k++) {
        c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      }
      t[n] = c >>> 0;
    }
    return t;
  })());
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime(date) {
  const d = date || new Date();
  const dosTime =
    ((d.getHours() & 0x1f) << 11) |
    ((d.getMinutes() & 0x3f) << 5) |
    ((Math.floor(d.getSeconds() / 2)) & 0x1f);
  const dosDate =
    (((d.getFullYear() - 1980) & 0x7f) << 9) |
    (((d.getMonth() + 1) & 0xf) << 5) |
    (d.getDate() & 0x1f);
  return { dosTime, dosDate };
}

function makeZip(files) {
  // files: [{ name: string, data: Buffer }]
  const localChunks = [];
  const centralChunks = [];
  let offset = 0;
  const { dosTime, dosDate } = dosDateTime();

  for (const file of files) {
    const nameBuf = Buffer.from(file.name, 'utf8');
    const rawData = file.data;
    const crc = crc32(rawData);
    const dataToStore = rawData; // stored, uncompressed — no zlib needed
    const method = 0;

    // Local file header
    const localHeader = Buffer.alloc(30);
    localHeader.writeUInt32LE(0x04034b50, 0);   // local file header signature
    localHeader.writeUInt16LE(20, 4);           // version needed
    localHeader.writeUInt16LE(0, 6);            // flags
    localHeader.writeUInt16LE(method, 8);       // compression method
    localHeader.writeUInt16LE(dosTime, 10);
    localHeader.writeUInt16LE(dosDate, 12);
    localHeader.writeUInt32LE(crc, 14);
    localHeader.writeUInt32LE(dataToStore.length, 18); // compressed size
    localHeader.writeUInt32LE(rawData.length, 22);     // uncompressed size
    localHeader.writeUInt16LE(nameBuf.length, 26);
    localHeader.writeUInt16LE(0, 28);           // extra field length

    localChunks.push(localHeader, nameBuf, dataToStore);

    // Central directory header
    const centralHeader = Buffer.alloc(46);
    centralHeader.writeUInt32LE(0x02014b50, 0);  // central dir signature
    centralHeader.writeUInt16LE(20, 4);          // version made by
    centralHeader.writeUInt16LE(20, 6);          // version needed
    centralHeader.writeUInt16LE(0, 8);           // flags
    centralHeader.writeUInt16LE(method, 10);
    centralHeader.writeUInt16LE(dosTime, 12);
    centralHeader.writeUInt16LE(dosDate, 14);
    centralHeader.writeUInt32LE(crc, 16);
    centralHeader.writeUInt32LE(dataToStore.length, 20);
    centralHeader.writeUInt32LE(rawData.length, 24);
    centralHeader.writeUInt16LE(nameBuf.length, 28);
    centralHeader.writeUInt16LE(0, 30);          // extra field length
    centralHeader.writeUInt16LE(0, 32);          // comment length
    centralHeader.writeUInt16LE(0, 34);          // disk number start
    centralHeader.writeUInt16LE(0, 36);          // internal attrs
    centralHeader.writeUInt32LE(0, 38);          // external attrs
    centralHeader.writeUInt32LE(offset, 42);     // relative offset of local header

    centralChunks.push(centralHeader, nameBuf);

    offset += localHeader.length + nameBuf.length + dataToStore.length;
  }

  const centralDirStart = offset;
  const centralDirBuf = Buffer.concat(centralChunks);
  const centralDirSize = centralDirBuf.length;

  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);        // EOCD signature
  eocd.writeUInt16LE(0, 4);                 // disk number
  eocd.writeUInt16LE(0, 6);                 // disk with central dir
  eocd.writeUInt16LE(files.length, 8);      // entries on this disk
  eocd.writeUInt16LE(files.length, 10);     // total entries
  eocd.writeUInt32LE(centralDirSize, 12);
  eocd.writeUInt32LE(centralDirStart, 16);
  eocd.writeUInt16LE(0, 20);                // comment length

  return Buffer.concat([...localChunks, centralDirBuf, eocd]);
}

// ============================================================================
// XML HELPERS
// ============================================================================

function xmlEscape(str) {
  return String(str ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function colLetter(n) {
  let s = '';
  while (n > 0) {
    const m = (n - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    n = Math.floor((n - m) / 26);
  }
  return s;
}

function cellRef(col, row) {
  return `${colLetter(col)}${row}`;
}

// ============================================================================
// STYLE REGISTRY (fonts, fills, borders, alignment -> single style index)
// ============================================================================

function createStyleRegistry() {
  const fonts = [{ name: 'Arial', size: 10 }]; // index 0 = default
  const fills = [{ type: 'none' }, { type: 'gray125' }]; // 0,1 reserved by spec
  const borders = [{ none: true }]; // index 0 = no border
  const xfs = [{ fontId: 0, fillId: 0, borderId: 0, align: null, numFmtId: 0 }]; // index 0 = default

  const cache = new Map();

  function addFont(font) {
    const key = JSON.stringify(font);
    let idx = fonts.findIndex((f) => JSON.stringify(f) === key);
    if (idx === -1) {
      fonts.push(font);
      idx = fonts.length - 1;
    }
    return idx;
  }

  function addFill(argb) {
    if (!argb) return 0;
    const key = JSON.stringify({ argb });
    let idx = fills.findIndex((f) => JSON.stringify(f) === key);
    if (idx === -1) {
      fills.push({ argb });
      idx = fills.length - 1;
    }
    return idx;
  }

  function addBorder(hasBorder) {
    if (!hasBorder) return 0;
    const key = JSON.stringify({ thin: true });
    let idx = borders.findIndex((b) => JSON.stringify(b) === key);
    if (idx === -1) {
      borders.push({ thin: true });
      idx = borders.length - 1;
    }
    return idx;
  }

  // opts: { bold, size, fontColor, fillColor, border, wrap, valign, halign, indent }
  function getStyle(opts = {}) {
    const key = JSON.stringify(opts);
    if (cache.has(key)) return cache.get(key);

    const fontId = addFont({
      name: 'Arial',
      size: opts.size || 10,
      bold: !!opts.bold,
      color: opts.fontColor || 'FF000000',
    });
    const fillId = addFill(opts.fillColor);
    const borderId = addBorder(opts.border !== false); // default true (thin border)

    const xf = {
      fontId,
      fillId,
      borderId,
      align: {
        vertical: opts.valign || 'top',
        horizontal: opts.halign || 'left',
        wrapText: opts.wrap !== false,
        indent: opts.indent || 0,
      },
      numFmtId: 0,
    };
    xfs.push(xf);
    const idx = xfs.length - 1;
    cache.set(key, idx);
    return idx;
  }

  function buildStylesXml() {
    const fontsXml = fonts.map((f) => {
      if (!f.bold && !f.color && f.size === 10 && f.name === 'Arial' && fonts.indexOf(f) === 0) {
        return `<font><sz val="10"/><name val="Arial"/></font>`;
      }
      return `<font>${f.bold ? '<b/>' : ''}<sz val="${f.size || 10}"/><color rgb="${f.color || 'FF000000'}"/><name val="${f.name || 'Arial'}"/></font>`;
    }).join('');

    const fillsXml = fills.map((f, i) => {
      if (i === 0) return `<fill><patternFill patternType="none"/></fill>`;
      if (i === 1) return `<fill><patternFill patternType="gray125"/></fill>`;
      return `<fill><patternFill patternType="solid"><fgColor rgb="${f.argb}"/><bgColor rgb="${f.argb}"/></patternFill></fill>`;
    }).join('');

    const borderThin = '<color rgb="FFE0DFD8"/>';
    const bordersXml = borders.map((b, i) => {
      if (i === 0 || b.none) {
        return `<border><left/><right/><top/><bottom/><diagonal/></border>`;
      }
      return `<border><left style="thin">${borderThin}</left><right style="thin">${borderThin}</right><top style="thin">${borderThin}</top><bottom style="thin">${borderThin}</bottom><diagonal/></border>`;
    }).join('');

    const xfsXml = xfs.map((xf) => {
      const align = xf.align
        ? `<alignment vertical="${xf.align.vertical}" horizontal="${xf.align.horizontal}" wrapText="${xf.align.wrapText ? 1 : 0}"${xf.align.indent ? ` indent="${xf.align.indent}"` : ''}/>`
        : '';
      return `<xf numFmtId="${xf.numFmtId}" fontId="${xf.fontId}" fillId="${xf.fillId}" borderId="${xf.borderId}" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1">${align}</xf>`;
    }).join('');

    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<fonts count="${fonts.length}">${fontsXml}</fonts>
<fills count="${fills.length}">${fillsXml}</fills>
<borders count="${borders.length}">${bordersXml}</borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="${xfs.length}">${xfsXml}</cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;
  }

  return { getStyle, buildStylesXml };
}

// ============================================================================
// WORKSHEET BUILDER
// ============================================================================

function createWorksheet(name) {
  const cells = new Map(); // "col,row" -> { value, styleId, isNumber }
  const merges = [];
  const colWidths = new Map();
  let rowHeightsMap = new Map();
  let maxCol = 1;
  let maxRow = 1;
  let showGridLines = true;

  function setCell(col, row, value, styleId) {
    maxCol = Math.max(maxCol, col);
    maxRow = Math.max(maxRow, row);
    cells.set(`${col},${row}`, { value, styleId: styleId || 0 });
  }

  function setColWidth(col, width) {
    colWidths.set(col, width);
  }

  function setRowHeight(row, height) {
    rowHeightsMap.set(row, height);
  }

  // Merge a rectangular range and stamp every cell in it with `styleId`.
  // Only the top-left cell carries `value`.
  function mergeBlock({ col1, col2, row1, row2, value, styleId }) {
    merges.push(`${cellRef(col1, row1)}:${cellRef(col2, row2)}`);
    for (let r = row1; r <= row2; r++) {
      for (let c = col1; c <= col2; c++) {
        const isTopLeft = r === row1 && c === col1;
        setCell(c, r, isTopLeft ? value : undefined, styleId);
      }
    }
  }

  function setShowGridLines(val) {
    showGridLines = val;
  }

  function buildSheetXml() {
    // group cells by row
    const rows = new Map();
    for (const [key, cellData] of cells.entries()) {
      const [c, r] = key.split(',').map(Number);
      if (!rows.has(r)) rows.set(r, []);
      rows.get(r).push({ col: c, ...cellData });
    }

    const sortedRowNums = Array.from(rows.keys()).sort((a, b) => a - b);

    const rowsXml = sortedRowNums.map((rNum) => {
      const rowCells = rows.get(rNum).sort((a, b) => a.col - b.col);
      const cellsXml = rowCells.map((cd) => {
        const ref = cellRef(cd.col, rNum);
        const sAttr = cd.styleId ? ` s="${cd.styleId}"` : '';
        if (cd.value === undefined || cd.value === null || cd.value === '') {
          return `<c r="${ref}"${sAttr}/>`;
        }
        return `<c r="${ref}"${sAttr} t="inlineStr"><is><t xml:space="preserve">${xmlEscape(cd.value)}</t></is></c>`;
      }).join('');
      const heightAttr = rowHeightsMap.has(rNum) ? ` ht="${rowHeightsMap.get(rNum)}" customHeight="1"` : '';
      return `<row r="${rNum}"${heightAttr}>${cellsXml}</row>`;
    }).join('');

    const colsXml = colWidths.size
      ? `<cols>${Array.from(colWidths.entries()).map(([c, w]) => `<col min="${c}" max="${c}" width="${w}" customWidth="1"/>`).join('')}</cols>`
      : '';

    const mergesXml = merges.length
      ? `<mergeCells count="${merges.length}">${merges.map((m) => `<mergeCell ref="${m}"/>`).join('')}</mergeCells>`
      : '';

    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<sheetViews><sheetView showGridLines="${showGridLines ? 1 : 0}" workbookViewId="0"/></sheetViews>
<sheetFormatPr defaultRowHeight="15"/>
${colsXml}
<sheetData>${rowsXml}</sheetData>
${mergesXml}
</worksheet>`;
  }

  return { name, setCell, setColWidth, setRowHeight, mergeBlock, setShowGridLines, buildSheetXml };
}

// ============================================================================
// WORKBOOK
// ============================================================================

function buildWorkbookFiles(worksheets) {
  const files = [];

  files.push({
    name: '[Content_Types].xml',
    data: Buffer.from(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
${worksheets.map((_, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('\n')}
</Types>`, 'utf8'),
  });

  files.push({
    name: '_rels/.rels',
    data: Buffer.from(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`, 'utf8'),
  });

  files.push({
    name: 'xl/workbook.xml',
    data: Buffer.from(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheets>${worksheets.map((ws, i) => `<sheet name="${xmlEscape(ws.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join('')}</sheets>
</workbook>`, 'utf8'),
  });

  files.push({
    name: 'xl/_rels/workbook.xml.rels',
    data: Buffer.from(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
${worksheets.map((_, i) => `<Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join('\n')}
<Relationship Id="rId${worksheets.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>`, 'utf8'),
  });

  worksheets.forEach((ws, i) => {
    files.push({
      name: `xl/worksheets/sheet${i + 1}.xml`,
      data: Buffer.from(ws.buildSheetXml(), 'utf8'),
    });
  });

  return files;
}

// ============================================================================
// CANVAS-SPECIFIC BUILD LOGIC (same layout as the original exceljs version)
// ============================================================================

const styleReg = createStyleRegistry();

const S = {
  title: styleReg.getStyle({ bold: true, size: 14, fontColor: 'FFFFFFFF', fillColor: 'FF1A1A18', valign: 'center', border: false, indent: 1, wrap: false }),
  label: styleReg.getStyle({ bold: true, size: 9, fontColor: 'FF6B6B67', fillColor: 'FFF1EFE8' }),
  body: styleReg.getStyle({ fontColor: 'FF1A1A18' }),
  swotHeader: styleReg.getStyle({ bold: true, size: 9, fontColor: 'FF6B6B67', halign: 'center', border: false, wrap: false }),
  swotS: styleReg.getStyle({ fontColor: 'FF085041', fillColor: 'FFE1F5EE' }),
  swotW: styleReg.getStyle({ fontColor: 'FF712B13', fillColor: 'FFFAECE7' }),
  swotO: styleReg.getStyle({ fontColor: 'FF0C447C', fillColor: 'FFE6F1FB' }),
  swotT: styleReg.getStyle({ fontColor: 'FF633806', fillColor: 'FFFAEEDA' }),
};

function bulletText(lines) {
  if (Array.isArray(lines)) return lines.filter(Boolean).map((l) => `• ${l}`).join('\n');
  return lines || '';
}

function revenueText(streams) {
  if (!streams || !streams.length) return '';
  return streams.map((s) => `${s.name}: ${s.description}`).join('\n');
}

function block(ws, { col1, col2, rowStart, rowEnd, label, content, bodyStyle }) {
  ws.mergeBlock({ col1, col2, row1: rowStart, row2: rowStart, value: label, styleId: S.label });
  ws.mergeBlock({ col1, col2, row1: rowStart + 1, row2: rowEnd, value: bulletText(content), styleId: bodyStyle || S.body });
}

function buildWorkbookBuffer(data) {
  const bmc = data.businessModelCanvas || {};
  const lc = data.leanCanvas || {};
  const sw = data.swot || {};
  const meta = data.meta || {};
  const worksheets = [];

  // ====================== BMC SHEET ======================
  if (bmc.generated) {
    const ws = createWorksheet('Business Model Canvas');
    ws.setShowGridLines(false);
    for (let c = 1; c <= 10; c++) ws.setColWidth(c, 16);

    ws.mergeBlock({ col1: 1, col2: 10, row1: 1, row2: 1, value: `Business Model Canvas — ${meta.businessName || ''}`, styleId: S.title });
    ws.setRowHeight(1, 26);

    block(ws, { col1: 1, col2: 2, rowStart: 3, rowEnd: 10, label: 'Key Partners', content: bmc.keyPartners });
    block(ws, { col1: 3, col2: 4, rowStart: 3, rowEnd: 6, label: 'Key Activities', content: bmc.keyActivities });
    block(ws, { col1: 3, col2: 4, rowStart: 7, rowEnd: 10, label: 'Key Resources', content: bmc.keyResources });
    block(ws, {
      col1: 5, col2: 6, rowStart: 3, rowEnd: 10, label: 'Value Propositions',
      content: [...(bmc.valuePropositions?.items || []), ...(bmc.valuePropositions?.tags || [])],
    });
    block(ws, { col1: 7, col2: 8, rowStart: 3, rowEnd: 6, label: 'Customer Relationships', content: bmc.customerRelationships });
    block(ws, { col1: 7, col2: 8, rowStart: 7, rowEnd: 10, label: 'Channels', content: bmc.channels });
    block(ws, {
      col1: 9, col2: 10, rowStart: 3, rowEnd: 10, label: 'Customer Segments',
      content: [...(bmc.customerSegments?.items || []), ...(bmc.customerSegments?.tags || [])],
    });

    block(ws, { col1: 1, col2: 5, rowStart: 11, rowEnd: 14, label: 'Cost Structure — Fixed', content: bmc.costStructure?.fixed });
    block(ws, { col1: 6, col2: 10, rowStart: 11, rowEnd: 14, label: 'Cost Structure — Variable', content: bmc.costStructure?.variable });
    block(ws, { col1: 1, col2: 10, rowStart: 15, rowEnd: 18, label: 'Revenue Streams', content: revenueText(bmc.revenueStreams) });

    worksheets.push(ws);
  }

  // ====================== LEAN CANVAS SHEET ======================
  if (lc.generated) {
    const ws = createWorksheet('Lean Canvas');
    ws.setShowGridLines(false);
    for (let c = 1; c <= 10; c++) ws.setColWidth(c, 16);

    ws.mergeBlock({ col1: 1, col2: 10, row1: 1, row2: 1, value: `Lean Canvas — ${meta.businessName || ''}`, styleId: S.title });
    ws.setRowHeight(1, 26);

    block(ws, {
      col1: 1, col2: 2, rowStart: 3, rowEnd: 10, label: 'Problem',
      content: [...(lc.problem?.items || []), lc.problem?.existingAlternatives?.length ? '— Existing alternatives —' : null, ...(lc.problem?.existingAlternatives || [])].filter(Boolean),
    });
    block(ws, { col1: 3, col2: 4, rowStart: 3, rowEnd: 6, label: 'Solution', content: lc.solution });
    block(ws, { col1: 3, col2: 4, rowStart: 7, rowEnd: 10, label: 'Key Metrics', content: lc.keyMetrics });
    block(ws, {
      col1: 5, col2: 6, rowStart: 3, rowEnd: 10, label: 'Unique Value Proposition',
      content: [lc.uniqueValueProposition?.headline, lc.uniqueValueProposition?.concept].filter(Boolean),
    });
    block(ws, { col1: 7, col2: 8, rowStart: 3, rowEnd: 6, label: 'Unfair Advantage', content: lc.unfairAdvantage });
    block(ws, { col1: 7, col2: 8, rowStart: 7, rowEnd: 10, label: 'Channels', content: lc.channels });
    block(ws, { col1: 9, col2: 10, rowStart: 3, rowEnd: 6, label: 'Early Adopters', content: lc.customerSegments?.earlyAdopters });
    block(ws, { col1: 9, col2: 10, rowStart: 7, rowEnd: 10, label: 'Target Market', content: lc.customerSegments?.targetMarket });

    block(ws, { col1: 1, col2: 5, rowStart: 11, rowEnd: 14, label: 'Cost Structure', content: lc.costStructure });
    block(ws, { col1: 6, col2: 10, rowStart: 11, rowEnd: 14, label: 'Revenue Streams', content: revenueText(lc.revenueStreams) });

    worksheets.push(ws);
  }

  // ====================== SWOT SHEET ======================
  if (sw.generated) {
    const ws = createWorksheet('SWOT Analysis');
    ws.setShowGridLines(false);
    for (let c = 1; c <= 8; c++) ws.setColWidth(c, 18);

    ws.mergeBlock({ col1: 1, col2: 8, row1: 1, row2: 1, value: `SWOT Analysis — ${meta.businessName || ''}`, styleId: S.title });
    ws.setRowHeight(1, 26);

    ws.mergeBlock({ col1: 1, col2: 4, row1: 2, row2: 2, value: 'HELPFUL', styleId: S.swotHeader });
    ws.mergeBlock({ col1: 5, col2: 8, row1: 2, row2: 2, value: 'HARMFUL', styleId: S.swotHeader });

    block(ws, { col1: 1, col2: 4, rowStart: 3, rowEnd: 10, label: 'Strengths', content: sw.strengths, bodyStyle: S.swotS });
    block(ws, { col1: 5, col2: 8, rowStart: 3, rowEnd: 10, label: 'Weaknesses', content: sw.weaknesses, bodyStyle: S.swotW });
    block(ws, { col1: 1, col2: 4, rowStart: 11, rowEnd: 18, label: 'Opportunities', content: sw.opportunities, bodyStyle: S.swotO });
    block(ws, { col1: 5, col2: 8, rowStart: 11, rowEnd: 18, label: 'Threats', content: sw.threats, bodyStyle: S.swotT });

    worksheets.push(ws);
  }

  // ====================== POSITIONING + NEXT STEPS SHEET ======================
  if (data.competitivePositioning?.length || data.nextSteps?.length) {
    const ws = createWorksheet('Positioning & Next Steps');
    ws.setShowGridLines(false);
    ws.setColWidth(1, 28);
    ws.setColWidth(2, 70);

    ws.mergeBlock({ col1: 1, col2: 2, row1: 1, row2: 1, value: 'Competitive Positioning', styleId: S.title });
    ws.setRowHeight(1, 24);

    ws.setCell(1, 2, 'Competitor', S.label);
    ws.setCell(2, 2, 'How We Differ', S.label);

    let r = 3;
    (data.competitivePositioning || []).forEach((row) => {
      ws.setCell(1, r, row.competitorName, S.body);
      ws.setCell(2, r, row.differentiation, S.body);
      r++;
    });

    r += 1;
    ws.mergeBlock({ col1: 1, col2: 2, row1: r, row2: r, value: 'Recommended Next Steps', styleId: S.title });
    r++;
    (data.nextSteps || []).forEach((step, i) => {
      ws.mergeBlock({ col1: 1, col2: 2, row1: r, row2: r, value: `${i + 1}. ${step}`, styleId: S.body });
      r++;
    });

    worksheets.push(ws);
  }

  const files = buildWorkbookFiles(worksheets);
  files.push({ name: 'xl/styles.xml', data: Buffer.from(styleReg.buildStylesXml(), 'utf8') });

  return makeZip(files);
}

// ============================================================================
// n8n ENTRY POINT
// ============================================================================

const raw = $input.first().json;

// Basic LLM Chain (and some Agent configurations) wrap the parsed structured
// output inside a key like `output`, `response`, or `text` (sometimes as a
// JSON string) instead of returning it flat. Unwrap whichever shape shows up
// so this script works regardless of which node type produced it.
function unwrapCanvasData(input) {
  const candidates = [
    input,
    input.output,
    input.response,
    input.response?.output,
    input.json,
  ];

  for (const candidate of candidates) {
    if (candidate && typeof candidate === 'object' && ('businessModelCanvas' in candidate || 'meta' in candidate)) {
      return candidate;
    }
  }

  // Sometimes the parsed object arrives as a JSON string instead of an object.
  for (const key of ['output', 'text', 'response']) {
    if (typeof input[key] === 'string') {
      try {
        const parsed = JSON.parse(input[key]);
        if (parsed && (parsed.businessModelCanvas || parsed.meta)) return parsed;
      } catch (e) { /* not JSON, ignore */ }
    }
  }

  return null; // couldn't find recognizable canvas data anywhere
}

const data = unwrapCanvasData(raw);
const meta = data?.meta || {};

let zipBuffer;
if (data) {
  zipBuffer = buildWorkbookBuffer(data);
} else {
  // Nothing recognizable was found — instead of producing a silently empty
  // file, dump the raw input into a debug sheet so you can see exactly what
  // this node actually received and fix the upstream field path.
  const ws = createWorksheet('Debug — Raw Input');
  ws.setShowGridLines(true);
  ws.setColWidth(1, 100);
  ws.mergeBlock({
    col1: 1, col2: 1, row1: 1, row2: 1,
    value: 'No businessModelCanvas/meta found in input. Raw JSON below:',
    styleId: S.label,
  });
  const jsonText = JSON.stringify(raw, null, 2);
  const lines = jsonText.split('\n');
  lines.forEach((line, i) => {
    ws.setCell(1, i + 2, line, S.body);
  });
  const files = buildWorkbookFiles([ws]);
  files.push({ name: 'xl/styles.xml', data: Buffer.from(styleReg.buildStylesXml(), 'utf8') });
  zipBuffer = makeZip(files);
}

return [
  {
    json: {
      businessName: meta.businessName || 'business',
      dataFound: !!data,
    },
    binary: {
      data: {
        data: zipBuffer.toString('base64'),
        mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        fileName: `${(meta.businessName || 'business-canvas').replace(/[^a-z0-9]+/gi, '-')}.xlsx`,
      },
    },
  },
];
